#!/usr/bin/env node
/**
 * Generates src/lib/abi.generated.ts from the Foundry build output.
 *
 * The frontend never hand-maintains an ABI. Hand-written ABIs drift from the
 * contract silently — the call still typechecks, it just reverts at runtime in
 * front of a user. Running this in `predev`/`prebuild` makes drift a build
 * error instead.
 *
 * `--if-available` is for hosts that build the frontend without Foundry —
 * Vercel, Netlify, a Docker stage that only copies `frontend/`. There, the
 * committed generated files are the source of truth and this exits quietly
 * rather than failing the build. It still fails loudly when neither the
 * artifacts nor the generated files exist, because that is a real problem.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, "../../contracts/out");
const dest = resolve(here, "../src/lib/abi.generated.ts");

const WANTED = [
  ["TideRegistry", "TideRegistry.sol/TideRegistry.json"],
  ["TideVault", "TideVault.sol/TideVault.json"],
  ["MockERC20", "MockERC20.sol/MockERC20.json"],
  ["MockRouter", "MockRouter.sol/MockRouter.json"],
  ["MockAggregatorV3", "MockAggregatorV3.sol/MockAggregatorV3.json"],
];

import { readdirSync } from "node:fs";

const optional = process.argv.includes("--if-available");

// The deployment mirror is plain JSON and never needs Foundry, so it is
// written before the artifact check. Skipping it on a Foundry-less host is
// how a devnet address book once survived into production and made the app
// claim a deployment existed on a chain where the addresses held no code.
writeDeployments();

if (!existsSync(out)) {
  if (optional && existsSync(dest)) {
    console.log("  contracts/out not found — using the committed generated files.");
    process.exit(0);
  }
  console.error(
    `\n  contracts/out not found.\n` +
      `  Run \`cd contracts && forge build\` first,\n` +
      `  or commit src/lib/abi.generated.ts if this host has no Foundry.\n`
  );
  process.exit(1);
}

let src = `// GENERATED by scripts/sync-contracts.mjs — do not edit.
// Source of truth: contracts/src/*.sol compiled with Foundry.
// Regenerate with: pnpm sync:contracts

`;

for (const [name, path] of WANTED) {
  const file = resolve(out, path);
  if (!existsSync(file)) {
    console.error(`  missing artifact: ${path}`);
    process.exit(1);
  }
  const artifact = JSON.parse(readFileSync(file, "utf8"));
  // Drop the constructor: it is never callable from the frontend and its
  // presence makes wagmi's function-name inference noisier.
  const abi = artifact.abi.filter((e) => e.type !== "constructor");
  src += `export const ${name.charAt(0).toLowerCase() + name.slice(1)}Abi = ${JSON.stringify(abi, null, 2)} as const;\n\n`;
}

mkdirSync(dirname(dest), { recursive: true });
writeFileSync(dest, src);
console.log(`  abi.generated.ts  ${WANTED.map(([n]) => n).join(", ")}`);

console.log(`  deployments.generated.ts  chains: ${Object.keys(deployments).join(", ") || "none"}`);

function writeDeployments() {
  /* ── deployments ──────────────────────────────────────────────────────────
     Whatever `forge script` last broadcast becomes the frontend's default
     address book, so a local devnet needs no manual copy-paste step. Env vars
     still win, which is how Vercel points at a real deployment.            */

  const depDir = resolve(here, "../../contracts/deployments");
  const depDest = resolve(here, "../src/lib/deployments.generated.ts");
  const deployments = {};

  if (existsSync(depDir)) {
    for (const f of readdirSync(depDir).filter((f) => f.endsWith(".json"))) {
      const chainId = Number(f.replace(".json", ""));
      if (!Number.isFinite(chainId)) continue;
      deployments[chainId] = JSON.parse(readFileSync(resolve(depDir, f), "utf8"));
    }
  }

  writeFileSync(
    depDest,
    `// GENERATED by scripts/sync-contracts.mjs — do not edit.
  // Mirrors contracts/deployments/*.json, written by the forge deploy scripts.

  export type GeneratedDeployment = {
    chainId: number;
    simulated: boolean;
    registry: \`0x\${string}\`;
    implementation: \`0x\${string}\`;
    quote: \`0x\${string}\`;
    quoteFeed: \`0x\${string}\`;
    router?: \`0x\${string}\`;
    targets?: \`0x\${string}\`[];
    feeds?: \`0x\${string}\`[];
    symbols?: string[];
  };

  export const generatedDeployments: Record<number, GeneratedDeployment> =
    ${JSON.stringify(deployments, null, 2)} as never;
  `
  );
}
